# frozen_string_literal: true

# Captures SQL during an operation to guard against N+1 query growth.
# Queries generated by schema introspection and the Rails query cache are excluded.
module SqlQueryRecorder
  def recorded_sql_queries
    queries = []
    listener = lambda do |_name, _started, _finished, _id, payload|
      next if payload[:cached] || %w[SCHEMA TRANSACTION].include?(payload[:name])

      queries << payload[:sql] if payload[:sql].present?
    end
    ActiveSupport::Notifications.subscribed(listener, 'sql.active_record') { yield }
    queries
  end
end
